#include <cstdio>
#include <vector>

int main() {
    int n;
    scanf("%d", &n);
    std::vector<long long> t(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &t[i]);

    std::vector<int> res(n, 0);
    std::vector<int> stk;
    for (int i = 0; i < n; ++i) {
        while (!stk.empty() && t[stk.back()] < t[i]) {
            int j = stk.back();
            stk.pop_back();
            res[j] = i - j;
        }
        stk.push_back(i);
    }

    for (int i = 0; i < n; ++i) {
        if (i) printf(" ");
        printf("%d", res[i]);
    }
    printf("\n");
    return 0;
}
